// PaymentForm.tsx - handleSubmit()
async handleSubmit(e) {
  e.preventDefault();

  if (!this.stripe) {
    this.setState({
      error: 'Payment system is temporarily unavailable. Please refresh and try again.',
      processing: false,
      buttonDisabled: false
    });
    // Log for monitoring
    console.error('Stripe instance not initialized - check CSP and network');
    return;
  }

  try {
    const { paymentMethod, error } = await this.stripe.createPaymentMethod({
      type: 'card',
      card: this.cardElement,
    });

    if (error) {
      this.setState({ error: error.message, processing: false });
      return;
    }

    // Safe access with optional chaining
    const chargeId = paymentMethod?.id;
    if (!chargeId) {
      throw new Error('Payment method creation returned no ID');
    }

    await this.processPayment(chargeId);
  } catch (err) {
    this.setState({ error: err.message, processing: false, buttonDisabled: false });
  }
}

