// AuthGuard.tsx
const MAX_REDIRECTS = 3;
const CLOCK_SKEW_TOLERANCE_MS = 60000; // 60 seconds

function isTokenValid(token: string): boolean {
  try {
    const payload = JSON.parse(atob(token.split('.')[1]));
    const now = Date.now() / 1000;
    // Add clock skew tolerance
    return payload.exp > (now - CLOCK_SKEW_TOLERANCE_MS / 1000);
  } catch {
    return false;
  }
}

// Redirect loop detection
function detectRedirectLoop(): boolean {
  const key = 'auth_redirect_count';
  const count = parseInt(sessionStorage.getItem(key) || '0');
  if (count >= MAX_REDIRECTS) {
    sessionStorage.removeItem(key);
    return true; // Loop detected
  }
  sessionStorage.setItem(key, String(count + 1));
  setTimeout(() => sessionStorage.removeItem(key), 10000);
  return false;
}

